let cart = [];

function initMenu() {
    const grid = document.getElementById('menu-grid');
    const special = document.getElementById('special-item');
    
    // Set first item as special
    const sp = menuData[0];
    special.innerHTML = `
        <div class="special-flex" style="display:flex; align-items:center; gap:30px; flex-wrap:wrap;">
            <img src="${sp.img}" style="width:250px; height:180px; object-fit:cover; border-radius:15px; border:2px solid var(--gold);">
            <div style="flex:1; min-width:250px;">
                <h2 style="color:var(--gold); margin-bottom:10px;">${sp.name}</h2>
                <p style="margin-bottom:15px; font-size:0.95rem;">Our signature chef-curated selection of fresh Nigiri, hand-pressed and served with artisanal soy sauce.</p>
                <h3 style="font-size:1.5rem; margin-bottom:15px;">¥${sp.price}</h3>
                <button class="add-btn" onclick="addToCart(${sp.id})" style="background:var(--gold); color:black; width:auto; padding:12px 30px;">Add Special to Cart</button>
            </div>
        </div>
    `;

    // Render 15 items in the grid
    menuData.slice(1).forEach(item => {
        grid.innerHTML += `
            <div class="menu-item">
                <img src="${item.img}">
                <h4>${item.name}</h4>
                <p style="color:var(--sakura); font-weight:bold; margin:5px 0;">¥${item.price}</p>
                <button class="add-btn" onclick="addToCart(${item.id})">Add to Cart</button>
            </div>`;
    });
}

function addToCart(id) {
    const product = menuData.find(item => item.id === id);
    const cartItem = cart.find(item => item.id === id);

    if (cartItem) {
        cartItem.qty++;
    } else {
        cart.push({ ...product, qty: 1 });
    }
    renderCart();
}

function renderCart() {
    const cartItemsList = document.getElementById('cart-items');
    const totalDisplay = document.getElementById('cart-total');
    const countDisplay = document.getElementById('cart-count');
    
    cartItemsList.innerHTML = "";
    let total = 0;

    if (cart.length === 0) {
        cartItemsList.innerHTML = '<p class="empty-msg">Your cart is empty.</p>';
    }

    cart.forEach(item => {
        total += item.price * item.qty;
        cartItemsList.innerHTML += `
            <div class="cart-item-row">
                <span>${item.name} (x${item.qty})</span>
                <span>¥${item.price * item.qty}</span>
            </div>`;
    });

    totalDisplay.innerText = total;
    countDisplay.innerText = cart.reduce((acc, curr) => acc + curr.qty, 0);
}

function toggleCart() {
    document.getElementById('cart-sidebar').classList.toggle('active');
}

function addReview() {
    const revInput = document.getElementById('revText');
    const reviewList = document.getElementById('review-list');
    if (revInput.value.trim() === "") return;

    const newRev = document.createElement('div');
    newRev.className = 'rev';
    newRev.innerHTML = `⭐ "${revInput.value}" - Verified Diner`;
    
    reviewList.prepend(newRev);
    revInput.value = "";
}

function processOrder() {
    if (cart.length === 0) {
        alert("Your cart is empty, Chief!");
        return;
    }
    alert("Order Placed Successfully! Your Japanese feast is being prepared.");
    cart = [];
    renderCart();
    toggleCart();
}

initMenu();